'use strict';

// MODULES //

var Float64Array = require( '@stdlib/array/float64' );
var abs = require( '@stdlib/math/base/special/abs' );
var min = require( '@stdlib/math/base/special/min' );
var max = require( '@stdlib/math/base/special/max' );
var data = require( './fixtures/lapack.json' ).cases;


// FUNCTIONS //

/**
* Packs selected entries into a padded typed view with a byte offset.
*
* @private
* @param {Array} matrix - logical square matrix
* @param {integer} N - prefix order
* @param {string} uplo - triangle
* @param {integer} s1 - row stride
* @param {integer} s2 - column stride
* @param {integer} extra - leading guard length
* @returns {Object} view and offset
*/
function pack( matrix, N, uplo, s1, s2, extra ) {
	var offset;
	var length;
	var value;
	var view;
	var high;
	var low;
	var i;
	var j;

	low = min( 0, (N-1)*s1 ) + min( 0, (N-1)*s2 );
	high = max( 0, (N-1)*s1 ) + max( 0, (N-1)*s2 );
	offset = extra-low;
	length = extra+high-low+9;
	view = new Float64Array( length+8 ).subarray( 3, length+3 );
	for ( i = 0; i < view.length; i++ ) {
		view[ i ] = Infinity;
	}
	for ( j = 0; j < N; j++ ) {
		for ( i = 0; i < N; i++ ) {
			if ( (uplo === 'upper' && i <= j) || (uplo === 'lower' && i >= j) ) {
				value = matrix[ i ][ j ];
				view[ offset+(i*s1)+(j*s2) ] = ( value === '-0' ) ? -0.0 : value;
			}
		}
	}
	return {
		'view': view,
		'offset': offset
	};
}


// MAIN //

/**
* Registers mathematical and public contract checks for an implementation.
*
* @param {Function} tape - test registration
* @param {Function} fn - public numerical implementation
* @param {string} name - implementation label
*/
function register( tape, fn, name ) {
	tape( name+': signature, validated empty prefix and errors', function test( t ) {
		var invalid;
		var i;

		t.strictEqual( fn.length, 8, 'main arity' );
		t.strictEqual( fn.ndarray.length, 13, 'ndarray arity' );
		t.strictEqual( Object.getOwnPropertyDescriptor( fn, 'ndarray' ).writable, false, 'read-only method' );
		t.strictEqual( Object.getOwnPropertyDescriptor( fn, 'ndarray' ).enumerable, false, 'non-enumerable method' );
		t.strictEqual( fn( 'row-major', 'upper', 0, null, NaN, null, Infinity, null ), 1, 'empty main ignores unused storage/LD' );
		t.strictEqual( fn.ndarray( 'lower', 0, null, NaN, Infinity, null, null, 'x', undefined, null, null, 0, NaN ), 1, 'empty ndarray ignores all unused arguments' );
		t.throws( function badOrder() {
			fn( 'bad', 'upper', 0 );
		}, TypeError, 'layout validated before empty return' );
		t.throws( function badTriangle() {
			fn( 'row-major', 'all', 0 );
		}, TypeError, 'triangle validated before empty return' );
		invalid = [ -1, 0.5, NaN, Infinity, '1', null, undefined, 9007199254740992 ];
		for ( i = 0; i < invalid.length; i++ ) {
			( function check( value ) {
				t.throws( function badN() {
					fn( 'row-major', 'upper', value );
				}, RangeError, 'invalid prefix' );
				t.throws( function badND() {
					fn.ndarray( 'upper', value );
				}, RangeError, 'invalid ndarray prefix' );
			})( invalid[ i ] );
		}
		t.throws( function badLD() {
			fn( 'row-major', 'upper', 2, [], 1, [], 2, [] );
		}, RangeError, 'leading dimension' );
		t.throws( function badLD() {
			fn( 'column-major', 'upper', 2, [], 2, [], 1.5, [] );
		}, RangeError, 'factor leading dimension' );
		t.throws( function badStride() {
			fn.ndarray( 'upper', 1, [], 0.5, 1, 0, [], 1, 1, 0, [], 1, 0 );
		}, RangeError, 'fractional stride' );
		t.throws( function badOffset() {
			fn.ndarray( 'upper', 1, [], 1, 1, NaN, [], 1, 1, 0, [], 1, 0 );
		}, RangeError, 'nonfinite offset' );
		t.throws( function badScratch() {
			fn.ndarray( 'upper', 1, [], 1, 1, 0, [], 1, 1, 0, [], 0, 0 );
		}, RangeError, 'zero scratch stride' );
		t.end();
	});

	tape( name+': actual finite LAPACK fixtures in both storage orders', function test( t ) {
		var expected;
		var beforeA;
		var beforeF;
		var matrixA;
		var matrixF;
		var order;
		var value;
		var uplo;
		var work;
		var ld;
		var lf;
		var f;
		var N;
		var k;
		var z;
		var i;

		for ( k = 0; k < data.length; k++ ) {
			f = data[ k ];
			N = f.ncols;
			uplo = ( f.uplo.toUpperCase() === 'U' ) ? 'upper' : 'lower';
			for ( z = 0; z < 2; z++ ) {
				order = ( z === 0 ) ? 'row-major' : 'column-major';
				ld = N+3;
				lf = N+5;
				matrixA = pack( f.A, N, uplo, (z === 0) ? ld : 1, (z === 0) ? 1 : ld, 0 ).view;
				matrixF = pack( f.AF, N, uplo, (z === 0) ? lf : 1, (z === 0) ? 1 : lf, 0 ).view;
				beforeA = new Float64Array( matrixA );
				beforeF = new Float64Array( matrixF );
				work = new Float64Array( (2*N)+5 );
				for ( i = 0; i < work.length; i++ ) {
					work[i] = -123;
				}
				value = fn( order, uplo, N, matrixA, ld, matrixF, lf, work );
				expected = new Float64Array( f.workspace );
				t.strictEqual( value, f.result, f.name+': reference value' );
				t.deepEqual( work.subarray( 0, 2*N ), expected, 'reference scratch maxima' );
				t.deepEqual( matrixA, beforeA, 'A byte-view entries unchanged' );
				t.deepEqual( matrixF, beforeF, 'AF byte-view entries unchanged' );
				t.deepEqual( Array.prototype.slice.call( work, 2*N ), [ -123, -123, -123, -123, -123 ], 'scratch suffix guard' );
			}
		}
		t.end();
	});

	tape( name+': independent views, stored-column counterexample and scratch guards', function test( t ) {
		var expected;
		var choices;
		var matrixA;
		var matrixF;
		var beforeA;
		var beforeF;
		var offset;
		var value;
		var work;
		var a;
		var b;
		var c;
		var i;

		choices = [ [ 7, 2 ], [ -7, 2 ], [ 2, -7 ], [ -2, -7 ] ];
		for ( a = 0; a < choices.length; a++ ) {
			for ( b = 0; b < choices.length; b++ ) {
				for ( c = -3; c <= 3; c += 2 ) {
					matrixA = pack( [ [1, 1000, 3], [0, 2, 2], [0, 0, 3] ], 3, 'upper', choices[a][0], choices[a][1], 4 );
					matrixF = pack( [ [2, 4, 6], [0, 4, 5], [0, 0, 6] ], 3, 'upper', choices[b][0], choices[b][1], 6 );
					beforeA = new Float64Array( matrixA.view );
					beforeF = new Float64Array( matrixF.view );
					offset = ( c < 0 ) ? 4+(5*abs(c)) : 4;
					work = new Float64Array( 12+(5*abs(c)) ).subarray( 2 );
					expected = new Float64Array( work.length );
					for ( i = 0; i < work.length; i++ ) {
						work[i] = -71;
						expected[i] = -71;
					}
					for ( i = 0; i < 6; i++ ) {
						expected[ offset+(i*c) ] = [ 2, 4, 6, 1, 1000, 3 ][i];
					}
					value = fn.ndarray( 'upper', 3, matrixA.view, choices[a][0], choices[a][1], matrixA.offset, matrixF.view, choices[b][0], choices[b][1], matrixF.offset, work, c, offset );
					t.strictEqual( value, 0.5, 'column-wise ratio differs from global-max ratio' );
					t.deepEqual( work, expected, 'all strided scratch entries and guards' );
					t.deepEqual( matrixA.view, beforeA, 'independent A view unchanged' );
					t.deepEqual( matrixF.view, beforeF, 'independent AF view unchanged' );
				}
			}
		}
		t.end();
	});

	tape( name+': zero read strides, readonly input alias and explicit comparison semantics', function test( t ) {
		var work;
		var AF;
		var sa;
		var sf;
		var A;
		var i;
		var j;

		for ( i = 0; i < 3; i++ ) {
			for ( j = 0; j < 3; j++ ) {
				sa = [ [0, 0], [0, 1], [1, 0] ][i];
				sf = [ [0, 0], [0, 1], [1, 0] ][j];
				A = new Float64Array( [1, 1, 1] );
				AF = new Float64Array( [2, 2, 2] );
				work = new Float64Array( 6 );
				t.strictEqual( fn.ndarray( 'lower', 3, A, sa[0], sa[1], 0, AF, sf[0], sf[1], 0, work, 1, 0 ), 0.5, 'zero-stride read view formula' );
				t.deepEqual( work, new Float64Array( [2, 2, 2, 1, 1, 1] ), 'zero-stride maxima' );
			}
		}
		A = new Float64Array( [1, 2, 3, 4] );
		work = new Float64Array( 4 );
		t.strictEqual( fn( 'row-major', 'lower', 2, A, 2, A, 2, work ), 1, 'readonly input alias supported' );
		t.deepEqual( A, new Float64Array( [1, 2, 3, 4] ), 'aliased inputs unchanged' );
		work = new Float64Array( 2 );
		t.strictEqual( fn( 'row-major', 'upper', 1, new Float64Array([NaN]), 1, new Float64Array([2]), 1, work ), 0, 'own NaN comparison policy, not universal reference parity' );
		t.deepEqual( work, new Float64Array([2, 0]), 'NaN ignored by explicit greater comparison' );
		t.strictEqual( fn( 'row-major', 'upper', 1, new Float64Array([Infinity]), 1, new Float64Array([Infinity]), 1, work ), 1, 'unordered ratio leaves cap unchanged' );
		t.strictEqual( fn( 'row-major', 'upper', 1, new Float64Array([-0.0]), 1, new Float64Array([-0.0]), 1, work ), 1, 'zero denominator ignored' );
		t.strictEqual( 1/work[0], Infinity, 'maxima have positive zero' );
		t.end();
	});
}


// EXPORTS //

module.exports = register;
